    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }
static inline uint32_t be32(const uint8_t *p){
    return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];
}

static void sha256_block(uint32_t state[8], const uint8_t block[64]){
    uint32_t W[64];
    for(int i=0;i<16;i++) W[i]=be32(block+4*i);
    for(int i=16;i<64;i++){
        uint32_t s0 = rotr(W[i-15],7)^rotr(W[i-15],18)^(W[i-15]>>3);
        uint32_t s1 = rotr(W[i-2],17)^rotr(W[i-2],19)^(W[i-2]>>10);
        W[i] = W[i-16]+s0+W[i-7]+s1;
    }
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3];
    uint32_t e=state[4],f=state[5],g=state[6],h=state[7];
    for(int i=0;i<64;i++){
        uint32_t S1 = rotr(e,6)^rotr(e,11)^rotr(e,25);
        uint32_t ch = (e&f)^((~e)&g);
        uint32_t t1 = h+S1+ch+K[i]+W[i];
        uint32_t S0 = rotr(a,2)^rotr(a,13)^rotr(a,22);
        uint32_t maj = (a&b)^(a&c)^(b&c);
        uint32_t t2 = S0+maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

/* 4 blocks at once: compute W schedules with AVX2, then 4 independent compressions.
   This does NOT produce a single chained hash faster; it's for throughput of independent blocks.
   For a single hash we need chaining. So this file also exports a single-hash scalar for baseline,
   and a function that hashes 4 independent messages (not useful here).
*/

void sha256_ref(const uint8_t *data, size_t len, uint8_t out[32]){
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nblocks = len/64;
    for(size_t i=0;i<nblocks;i++) sha256_block(state, data+i*64);
    uint8_t tail[128];
    size_t rem = len%64;
    memcpy(tail, data+nblocks*64, rem);
    tail[rem]=0x80;
    size_t pad = (rem<56)?64:(128);
    memset(tail+rem+1, 0, pad-rem-1);
    uint64_t bits = (uint64_t)len*8;
    for(int i=0;i<8;i++) tail[pad-1-i] = (uint8_t)(bits>>(8*i));
    sha256_block(state, tail);
    if(pad==128) sha256_block(state, tail+64);
    for(int i=0;i<8;i++){
        out[4*i]=(uint8_t)(state[i]>>24);
        out[4*i+1]=(uint8_t)(state[i]>>16);
        out[4*i+2]=(uint8_t)(state[i]>>8);
        out[4*i+3]=(uint8_t)state[i];
    }
}
