#define ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))
#define S0(x) (ROTR(x,2)^ROTR(x,13)^ROTR(x,22))
#define S1(x) (ROTR(x,6)^ROTR(x,11)^ROTR(x,25))
#define s0(x) (ROTR(x,7)^ROTR(x,18)^((x)>>3))
#define s1(x) (ROTR(x,17)^ROTR(x,19)^((x)>>10))
#define CH(e,f,g) (((e)&(f))^((~(e))&(g)))
#define MAJ(a,b,c) (((a)&(b))^((a)&(c))^((b)&(c)))

#define RND(a,b,c,d,e,f,g,h,k,w) do { \
    uint32_t t1 = (h) + S1(e) + CH(e,f,g) + (k) + (w); \
    uint32_t t2 = S0(a) + MAJ(a,b,c); \
    (h)=g; (g)=f; (f)=e; (e)=(d)+t1; (d)=c; (c)=b; (b)=a; (a)=t1+t2; \
} while(0)

/* byte swap 8 lanes of 32-bit using shuffle */
static inline __m256i bswap32_8(__m256i x){
    const __m256i mask = _mm256_set_epi8(
        12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3,
        12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    return _mm256_shuffle_epi8(x, mask);
}

static inline __m256i sigma0(__m256i x){
    /* rotr7 ^ rotr18 ^ shr3 */
    __m256i r7  = _mm256_or_si256(_mm256_srli_epi32(x,7),  _mm256_slli_epi32(x,25));
    __m256i r18 = _mm256_or_si256(_mm256_srli_epi32(x,18), _mm256_slli_epi32(x,14));
    __m256i s3  = _mm256_srli_epi32(x,3);
    return _mm256_xor_si256(_mm256_xor_si256(r7, r18), s3);
}
static inline __m256i sigma1(__m256i x){
    __m256i r17 = _mm256_or_si256(_mm256_srli_epi32(x,17), _mm256_slli_epi32(x,15));
    __m256i r19 = _mm256_or_si256(_mm256_srli_epi32(x,19), _mm256_slli_epi32(x,13));
    __m256i s10 = _mm256_srli_epi32(x,10);
    return _mm256_xor_si256(_mm256_xor_si256(r17, r19), s10);
}

/* Alignr-style for 32-bit lanes across 128-bit halves is annoying.
   Compute W schedule in scalar but unrolled, rounds fully unrolled.
   That's often what compilers do well. Let's just fully unroll scalar
   with W in regs as much as possible — compiler + manual unroll.
*/

__attribute__((noinline))
static void sha256_block_scalar(uint32_t st[8], const uint8_t *blk){
    uint32_t W[64];
    /* load + bswap */
    const uint32_t *p = (const uint32_t*)blk;
    for(int i=0;i<16;i++) W[i]=__builtin_bswap32(p[i]);
    for(int i=16;i<64;i++){
        W[i]=W[i-16]+s0(W[i-15])+W[i-7]+s1(W[i-2]);
    }
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    #pragma unroll
    for(int i=0;i<64;i++){
        RND(a,b,c,d,e,f,g,h,K256[i],W[i]);
    }
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

/* AVX2 message schedule: compute 4 W words at a time.
   W[i] = W[i-16] + s0(W[i-15]) + W[i-7] + s1(W[i-2])
   For a vector of W[i..i+3]:
     W[i-16..i-13] is previous vector 4 back
     s0(W[i-15..i-12]) needs a shift of the vector
   This is the classic SSSE3/AVX approach. We'll do it and extract to scalar rounds.
*/

static inline __m256i Wnext(__m256i w0, __m256i w1, __m256i w2, __m256i w3){
    /* w0 = W[i-16..i-13], w1=W[i-12..i-9], w2=W[i-8..i-5], w3=W[i-4..i-1]
       want W[i..i+3] = w0 + s0(W[i-15..i-12]) + W[i-7..i-4] + s1(W[i-2..i+1])
       W[i-15..i-12] = align(w0, w1) by 4 bytes? lanes are 32-bit so palignr by 4.
       But palignr is 128-bit. With AVX2, _mm256_alignr_epi8 works within 128 lanes.
       w0 lanes: [w_i-13, w_i-14, w_i-15, w_i-16 | w_i-9 ...] wait set order.
       We'll store W as little-endian lane order: lane0 = earliest.
       _mm256_loadu is lane0 = lowest address = earliest word. Good.
       alignr_epi8(a,b,4) within each 128: result = (b>>4) | (a<<12) in bytes,
       so lane-wise: result lanes = b's lanes shifted left by 1, with a's lane0 inserted at the end of the 128 half.
       That's NOT a full 256-bit shift. Need to handle the cross-lane at the 128 boundary.
    */
    /* 32-bit lane rotate across full 256:
       We want s = W[i-15], W[i-14], W[i-13], W[i-12] from w0=[i-16..i-13], w1=[i-12..i-9]
       s = {w0[1], w0[2], w0[3], w1[0]}  but w0 is 8 lanes: indices 0..7 = i-16..i-9 if we loaded 8.
       Let's redefine to operate on 128-bit (4 words) which is the classic way, using SSE.
       This function won't be used. */
    (void)w0;(void)w1;(void)w2;(void)w3;
    return w0;
}

void sha256_mine(const uint8_t *data, size_t len, uint8_t out[32]){
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t n = len/64;
    for(size_t i=0;i<n;i++) sha256_block_scalar(st, data+i*64);
    uint8_t tail[128];
    size_t rem = len%64;
    memcpy(tail, data+n*64, rem);
    tail[rem]=0x80;
    size_t pad = (rem<56)?64:128;
    memset(tail+rem+1, 0, pad-rem-1-8);
    uint64_t bits = (uint64_t)len*8;
    for(int i=0;i<8;i++) tail[pad-1-i]=(uint8_t)(bits>>(8*i));
    sha256_block_scalar(st, tail);
    if(pad==128) sha256_block_scalar(st, tail+64);
    for(int i=0;i<8;i++){
        uint32_t v=st[i];
        out[4*i]=v>>24; out[4*i+1]=v>>16; out[4*i+2]=v>>8; out[4*i+3]=v;
    }
}

int main(){
    size_t N=20*1000*1024;
    uint8_t *data=aligned_alloc(64,N);
    memset(data,0x5a,N);
    uint8_t a[32], b[32];
    sha256_mine(data,N,a);
    SHA256(data,N,b);
    printf("match %d\n", memcmp(a,b,32)==0);
    if(memcmp(a,b,32)){
        for(int i=0;i<32;i++) printf("%02x", a[i]); printf("\n");
        for(int i=0;i<32;i++) printf("%02x", b[i]); printf("\n");
    }
    mach_timebase_info_data_t tb; mach_timebase_info(&tb);
    int reps=4;
    for(int k=0;k<2;k++){
        const char *name = k==0?"mine":"ossl";
        double best=1e9;
        for(int i=0;i<reps;i++){
            uint64_t t0=mach_absolute_time();
            if(k==0) sha256_mine(data,N,a); else SHA256(data,N,b);
            double s=(double)(mach_absolute_time()-t0)*tb.numer/tb.denom/1e9;
            if(s<best) best=s;
        }
        printf("%s best %.1f MB/s\n", name, (N/1e6)/best);
    }
    return 0;
}
